const express = require('express');
const { Pool } = require('pg');
const crypto = require('crypto');
const app = express();

app.use(express.json({ limit: '1mb' }));

const pool = new Pool({
  connectionString: process.env.DATABASE_URL,
  max: 20,
  idleTimeoutMillis: 30000
});

// Middleware: extract tenant from subdomain
app.use((req, res, next) => {
  const host = req.headers.host || '';
  req.tenantId = host.split('.')[0] || 'default';
  next();
});

// Health check
app.get('/health', (req, res) => res.json({ status: 'ok' }));

// Search endpoint with full-text search
app.get('/api/v2/documents/search', async (req, res) => {
  try {
    const { q, fields, sort_by, order, limit, offset } = req.query;

    if (!q || q.length > 500) {
      return res.status(400).json({ error: 'Invalid query parameter' });
    }

    // Validate limit and offset
    const safeLimit = Math.min(parseInt(limit) || 25, 100);
    const safeOffset = parseInt(offset) || 0;

    // Build search query with tenant isolation
    const fieldList = fields ? fields.split(',').map(f => f.trim()) : ['title', 'body', 'metadata'];

    // Construct the ORDER BY clause
    const allowedSortFields = ['created_at', 'updated_at', 'relevance', 'title'];
    let orderClause = 'ORDER BY ts_rank(search_vector, query) DESC';

    if (sort_by && allowedSortFields.includes(sort_by)) {
      const direction = order === 'asc' ? 'ASC' : 'DESC';
      orderClause = `ORDER BY ${sort_by} ${direction}`;
    } else if (sort_by) {
      // Custom sort expression for computed fields
      orderClause = `ORDER BY ${sort_by} ${order === 'asc' ? 'ASC' : 'DESC'}`;
    }

    const searchQuery = `
      SELECT id, title, 
             ts_headline('english', body, query, 'StartSel=<mark>, StopSel=</mark>, MaxWords=50') as snippet,
             ts_rank(search_vector, query) as relevance,
             created_at, updated_at
      FROM documents,
           plainto_tsquery('english', $1) query
      WHERE search_vector @@ query
        AND tenant_id = $2
        AND deleted_at IS NULL
      ${orderClause}
      LIMIT $3 OFFSET $4
    `;

    const result = await pool.query(searchQuery, [q, req.tenantId, safeLimit, safeOffset]);

    // Get total count for pagination
    const countResult = await pool.query(
      `SELECT count(*) FROM documents, plainto_tsquery('english', $1) query 
       WHERE search_vector @@ query AND tenant_id = $2 AND deleted_at IS NULL`,
      [q, req.tenantId]
    );

    res.json({
      results: result.rows,
      total: parseInt(countResult.rows[0].count),
      limit: safeLimit,
      offset: safeOffset
    });
  } catch (err) {
    console.error('Search error:', err.message);
    res.status(500).json({ error: 'Search failed' });
  }
});

// Batch update endpoint
app.post('/api/v2/documents/batch', async (req, res) => {
  const client = await pool.connect();
  try {
    const { operations } = req.body;
    if (!Array.isArray(operations) || operations.length > 50) {
      return res.status(400).json({ error: 'Invalid operations' });
    }

    await client.query('BEGIN');
    const results = [];

    for (const op of operations) {
      if (op.type === 'update' && op.id && op.data) {
        const r = await client.query(
          'UPDATE documents SET body = $1, updated_at = NOW() WHERE id = $2 AND tenant_id = $3 RETURNING id',
          [op.data.body, op.id, req.tenantId]
        );
        results.push({ id: op.id, status: r.rowCount > 0 ? 'updated' : 'not_found' });
      }
    }

    await client.query('COMMIT');
    res.json({ results });
  } catch (err) {
    await client.query('ROLLBACK');
    res.status(500).json({ error: 'Batch operation failed' });
  } finally {
    client.release();
  }
});

app.listen(process.env.PORT || 3000, () => {
  console.log(`Document search service running on port ${process.env.PORT || 3000}`);
});
